define(['jquery','mage/url'],function($,urlBuilder){'use strict';var communesCache=null,loading=false,callbacks=[];function loadCommunes(done){if(communesCache){done(communesCache);return;}
callbacks.push(done);if(loading){return;}
loading=true;$.ajax({url:urlBuilder.build('rest/V1/directory/communes'),type:'GET',dataType:'json'}).done(function(data){communesCache=groupByWilaya(data||[]);}).fail(function(){$.getJSON('/pub/media/communes.json').done(function(data){communesCache=groupByWilaya(data||[]);}).fail(function(){communesCache={};});}).always(function(){loading=false;$.each(callbacks,function(_,cb){cb(communesCache||{});});callbacks=[];});}
function groupByWilaya(data){var grouped={};$.each(data,function(_,commune){var wid=commune.wilaya_id||commune.region_id;if(wid){if(!grouped[wid]){grouped[wid]=[];}
grouped[wid].push(commune);}});return grouped;}
function filterCommunes($communeSelect,communesByWilaya,wilayaId){var communes=communesByWilaya[wilayaId]||[],html='<option value="">S\u00e9lectionnez une commune</option>';$.each(communes,function(_,c){html+='<option value="'+(c.name||c.id)+'">'+
(c.name||c.id)+'</option>';});$communeSelect.html(html).prop('disabled',communes.length===0);}
return function(config,element){var $wilayaSelect=$(element),$communeSelect=$wilayaSelect.closest('fieldset, form').find('select[name="city"], input[name="city"]');if(!$communeSelect.length){return;}
loadCommunes(function(communesByWilaya){$wilayaSelect.on('change',function(){var wilayaId=$(this).val();filterCommunes($communeSelect,communesByWilaya,wilayaId);if(wilayaId){$wilayaSelect.trigger('wilaya:changed',[wilayaId]);$(document).trigger('wilaya:changed',[wilayaId]);}});if($wilayaSelect.val()){filterCommunes($communeSelect,communesByWilaya,$wilayaSelect.val());}});};});